def game_score(points: str) -> str:
    # mapping from raw point count to tennis score string
    score_map = {0: '0', 1: '15', 2: '30', 3: '40'}

    a, b = 0, 0  # point counters for A and B

    for p in points:
        # ignore any points after a game has been won
        if a >= 4 or b >= 4:
            break

        if p == 'A':
            a += 1
        elif p == 'B':
            b += 1
        else:
            # ignore invalid characters
            continue

        # Check for game win after each point
        if a >= 4 or b >= 4:
            break

    # Determine the result after processing
    if a >= 4 or b >= 4:
        winner = 'A' if a > b else 'B'
        return f'Game {winner}'

    # No one has won yet; determine current score
    # Special case: deuce (40-40)
    if a == 3 and b == 3:
        return '40-40'

    return f'{score_map.get(a, "0")}-{score_map.get(b, "0")}'
